void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image && image->next) {
    MagickCore::Image *nextFrame = image->next;
    while (nextFrame) {
      MagickCore::Image *temp = nextFrame;
      nextFrame = nextFrame->next;
      temp->next = NULL;
      DestroyImage(temp);
    }
  }

  if (image == NULL && exceptionInfo->severity == UndefinedException) {
    exceptionInfo = DestroyExceptionInfo(exceptionInfo);
    (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError, "NoImageRead", "Image not read");
  }

  if (image != NULL) {
    MagickCore::ExceptionInfo *imageException = CloneExceptionInfo(exceptionInfo);
    (void) ThrowMagickException(imageException, GetMagickModule(), image->exception.severity, image->exception.reason, image->exception.description);
    DestroyExceptionInfo(imageException);
  }
}

void ReadSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image != (MagickCore::Image *) NULL) {
    MagickCore::Image *nextFrame = image->next;

    while (nextFrame != (MagickCore::Image *) NULL) {
      MagickCore::Image *temp = nextFrame;
      nextFrame = nextFrame->next;
      temp->signature = 0;
      if (temp->columns != 0) {
        if (temp->storage_class == PseudoClass)
          (void)MagickCore::FreeImagePixels(temp);
        (void)MagickCore::FreeImage(temp);
      }
    }

    image->next = (MagickCore::Image *) NULL;
    image->previous = (MagickCore::Image *) NULL;

    if (image->exception.severity != UndefinedException &&
        image->exception.reason != (const char *) NULL) {
      if (image->columns == 0) {
        (void)MagickCore::DestroyException(exceptionInfo);
        (void)MagickCore::ThrowMagickException(exceptionInfo, GetMagickModule(), WarningException,
                                               "Image", "`%s'", image->exception.reason);
      } else {
        (void)MagickCore::ThrowMagickException(exceptionInfo, GetMagickModule(),
                                               image->exception.severity,
                                               "Image", "`%s'", image->exception.reason);
      }
    }
  } else {
    (void)MagickCore::DestroyException(exceptionInfo);
    (void)MagickCore::ThrowMagickException(exceptionInfo, GetMagickModule(), WarningException,
                                           "Image", "Image is null");
  }
}

void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image != (MagickCore::Image *) NULL) {
    MagickCore::Image *nextFrame = image->next;
    while (nextFrame != (MagickCore::Image *) NULL) {
      MagickCore::Image *temp = nextFrame->next;
      DestroyImage(nextFrame);
      nextFrame = temp;
    }
    ReplaceImageInList(&image, image);
  }

  if (exceptionInfo->severity == UndefinedException && image == (MagickCore::Image *) NULL) {
    DestroyExceptionInfo(exceptionInfo);
    (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError, "NoImage", "No image read");
  } else if (image != (MagickCore::Image *) NULL) {
    (void) ThrowMagickException(exceptionInfo, image->exception.severity, image->exception.reason, image->exception.description);
  }
}

