void ReadImage(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo)
{
    if (image != (MagickCore::Image *) NULL)
    {
        if (image->next != (MagickCore::Image *) NULL)
        {
            (void) DestroyImages(image->next);
            image->next = (MagickCore::Image *) NULL;
        }
        image->previous = (MagickCore::Image *) NULL;
    }
    else
    {
        exceptionInfo->severity = UndefinedException;
        if (image == (MagickCore::Image *) NULL)
        {
            (void) DestroyExceptionInfo(exceptionInfo);
            (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError,
              "NullImagePointer", "`%s' (image)", "no image");
            return;
        }
        (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError,
          "ImageReadError", "`%s' (image)", image->filename);
    }
}
